(()=>{let lang=new URLSearchParams(location.search).get('lang')==='es'?'es':'en';function render(){document.documentElement.lang=lang;document.querySelectorAll('[data-en]').forEach(e=>e.textContent=e.dataset[lang]);document.querySelector('#language').textContent=lang==='es'?'English':'Español';document.querySelector('#four-problem-route').href='../../../../diagnostics/?module=ad01&lang='+lang;const u=new URL(location.href);u.searchParams.set('lang',lang);history.replaceState(null,'',u);}document.querySelector('#language').onclick=()=>window.QuidenceI18n.setLocale(lang==='en'?'es':'en');document.addEventListener('quidence:language',e=>{lang=e.detail.locale;render();});render();})();